	// MT2009_PLUS_CLEAR_MISSIONS_V1 (letter): pc.clear_quest_letter("quest") for the
	// /usunmisje window (quest usun_misje). Another quest's letter goes off the
	// client's quest list at once - the quest-info "end" packet q.done() would send
	// from inside that quest - and its arrows off the map (its targets), so no
	// warp or relog is needed. Returns the quest's index (0: no such quest); the
	// client takes its letter button off with it.
	ALUA(pc_clear_quest_letter)
	{
		CQuestManager& q = CQuestManager::instance();
		PC* pPC = q.GetCurrentPC();
		LPCHARACTER ch = q.GetCurrentCharacterPtr();
		if (!lua_isstring(L, 1) || !pPC || !ch || !ch->GetDesc())
		{
			lua_pushnumber(L, 0);
			return 1;
		}
		const DWORD dwIndex = q.GetQuestIndexByName(lua_tostring(L, 1));
		if (!dwIndex)
		{
			lua_pushnumber(L, 0);
			return 1;
		}
		CTargetManager::instance().DeleteTarget(ch->GetPlayerID(), dwIndex, NULL);
		PC::QuestInfoIterator it = pPC->quest_find(dwIndex);
		if (it != pPC->quest_end())
			it->second.bStart = false;

		packet_quest_info qi;
		qi.header = HEADER_GC_QUEST_INFO;
		qi.size = sizeof(struct packet_quest_info) + sizeof(BYTE);
		qi.index = dwIndex;
#ifdef ENABLE_QUEST_CATEGORY
		qi.c_index = q.ReadQuestCategoryFile(dwIndex);
#endif
		qi.flag = PC::QUEST_SEND_ISBEGIN;
		const BYTE bBegin = 0;
		ch->GetDesc()->BufferedPacket(&qi, sizeof(qi));
		ch->GetDesc()->Packet(&bBegin, sizeof(bBegin));
		lua_pushnumber(L, dwIndex);
		return 1;
	}

